example_item.example_item_data:
z = nelson.io.zip.open([], 'w');
z.write('notes/hello.txt', 'Hello ZIP');
z.write('data.bin', uint8(1:100), 'Compression', 'store');
bytes = nelson.io.zip.tobytes(z);
r = nelson.io.zip.open(bytes);
nelson.io.zip.entries(r)
nelson.io.zip.readtext(r, 'notes/hello.txt')
nelson.io.zip.close(r);

filename = [tempdir(), 'nelson_io_zip_example.zip'];
z = nelson.io.zip.open(filename, 'w');
nelson.io.zip.add(z, [modulepath('file_archiver'), '/etc/startup.m']);
nelson.io.zip.close(z);
z = nelson.io.zip.open(filename, 'a');
z.write('readme.txt', "appended");
z.close();
r = nelson.io.zip.open(filename);
r.entries().Name
r.close();

z = nelson.io.zip.open([], 'w');
fid = z.fopen('table.csv', 'w');
fprintf(fid, '%d,%g\n', [1:3; (1:3) / 10]);
fclose(fid);
r = nelson.io.zip.open(z.tobytes());
fid = r.fopen('table.csv');
C = textscan(fid, '%d,%f')
fclose(fid);
r.close();

filename = [tempname(), '.zip'];
z = nelson.io.zip.open(filename, 'w', 'Password', 'secret', 'Encryption', 'aes256');
z.Encryption
z.write('notes/private.txt', 'Hidden text');
z.close();
r = nelson.io.zip.open(filename, 'r', 'Password', 'secret');
r.entries().Encrypted
r.readtext('notes/private.txt')
r.close();
delete(filename);
